head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > useLocale]<br/>툴팁, 각 아이템의 라벨값에 클라이언트 다국어 기능을 사용할지 설정합니다.",
    "validation" : [
        "true 설정 시 클라이언트 다국어 기능을 사용하여 툴팁, 각 아이템의 라벨에 해당 언어의 텍스트를 표시합니다.",
        "false (default) 설정 시 클라이언트 다국어 키를 사용하지 않습니다.",
        "useLocale 미설정 시 클라이언트 다국어 키를 사용하지 않습니다. (기본값 false)",
        "다국어 기능을 사용하려면 config.xml 파일에서 languagePack 항목을 설정하여야 합니다.",
        "다국어 기능은 Key:Value 형식으로 데이터가 정의된 JS 파일에서 Key 값에 해당하는 Value 값을 찾아 특정 속성에 반영합니다. 클라이언트(웹브라우저)에 설정된 언어에 해당하는 JS 파일이 적용됩니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cUseLocale = con_useLocale.getText();

    // 조건 설정
    let properties = {
        tooltip: "tooltip",
        tooltipLocaleRef: "websquare_name",
        useItemLocale: true
    };
    if (cUseLocale !== "") {
        properties.useLocale = cUseLocale;
    }

    let cList = $c.gcm.createCList(properties);
    let eHandler = 'ev:onclick="scwin.target1_onclick"';

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 다국어 검증을 위한 dataList 정의 (라벨이 다국어 Key)
    let strTarget = '';
    strTarget += '<xf:select ' + strNameSpace + ' ' + cList + ' ' + eHandler + ' id="" appearance="minimal" style="width:200px; height:80px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_multiselectLocale">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:select>';

    scwin.target1 = await $p.dynamicCreate('target1', 'multiselect', strTarget, grp_comp);
};



// target1 클릭 시 tooltip 풍선 정보 + 아이템 라벨 textContent 출력
// useLocale=true → 툴팁/라벨 다국어 적용
// useLocale=false 또는 미설정 → 툴팁/라벨 모두 다국어 미적용 (원본 텍스트 그대로)
scwin.target1_onclick = function (e) {
    // tooltip 풍선 (hover 시점에만 표시, null 안전 처리)
    var balloonLabel = document.querySelector('.w2balloonTip_label');
    var balloon = document.querySelector('.w2balloonTip');
    if (balloonLabel && balloon) {
        wf_body_bottom.getObj("scwin").setReturnValue("tooltip textContent : " + balloonLabel.textContent);
        wf_body_bottom.getObj("scwin").setReturnValue("tooltip display : " + balloon.style.display);
    }

    // multiselect 라벨 DOM textContent 출력 (accessibility=true 면 button, false 면 td)
    if (target1 && target1.render) {
        var labelEls = target1.render.querySelectorAll('button.w2multiselect_acc_link, td.w2multiselect_td');
        var labelTexts = [];
        for (var i = 0; i < labelEls.length; i++) {
            labelTexts.push(labelEls[i].textContent);
        }
        wf_body_bottom.getObj("scwin").setReturnValue("target1 item labels : [" + labelTexts.join(", ") + "]");
    }
};



// 현재 useLocale 속성 확인 (options 객체 직접 조회)
scwin.btn_getUseLocale_onclick = function (e) {
    var v = (target1 && target1.options) ? target1.options.useLocale : "";
    wf_body_bottom.getObj("scwin").setReturnValue("target1 useLocale 속성 : [" + v + "]");
};
